import "fmt"

type Stack[T any] struct{ items []T }

func (s *Stack[T]) Push(v T) { s.items = append(s.items, v) }

func (s *Stack[T]) Pop() (T, bool) {
	var zero T
	if len(s.items) == 0 {
		return zero, false
	}
	v := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return v, true
}

func main() {
	s := Stack[string]{}
	s.Push("a")
	s.Push("b")
	v1, _ := s.Pop()
	v2, _ := s.Pop()
	v3, ok := s.Pop()
	fmt.Printf("%s %s %q %v\n", v1, v2, v3, ok)
}

